#include <iostream>
#include <vector>
using namespace std;

// 全局变量
int m, n;
vector<vector<int>> maze;
vector<vector<bool>> visited;
vector<pair<int, int>> path;
bool found = false;

// 方向：左、上、右、下（注意题目要求优先顺序）
int dx[4] = {0, -1, 0, 1};
int dy[4] = {-1, 0, 1, 0};

// 检查坐标是否在迷宫范围内且可通行
bool isValid(int x, int y) {
    return x >= 1 && x <= m && y >= 1 && y <= n && maze[x][y] == 1 && !visited[x][y];
}

// 打印当前路径
void printPath(int startX, int startY, int endX, int endY) {
    for (int i = 0; i < path.size() - 1; ++i) {
        cout << "(" << path[i].first << "," << path[i].second << ")->";
    }
    cout << "(" << endX << "," << endY << ")" << endl;
}

// 深度优先搜索
void dfs(int x, int y, int endX, int endY) {
    if (x == endX && y == endY) {
        found = true;
        printPath(x, y, endX, endY);
        return;
    }

    for (int dir = 0; dir < 4; ++dir) {
        int nx = x + dx[dir];
        int ny = y + dy[dir];
        if (isValid(nx, ny)) {
            visited[nx][ny] = true;
            path.emplace_back(nx, ny);
            dfs(nx, ny, endX, endY);
            // 回溯
            visited[nx][ny] = false;
            path.pop_back();
        }
    }
}

int main() {
    // 读取迷宫大小
    cin >> m >> n;
    maze.resize(m + 1, vector<int>(n + 1, 0));
    visited.resize(m + 1, vector<bool>(n + 1, false));

    // 读取迷宫地图
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            cin >> maze[i][j];
        }
    }

    // 读取起点和终点
    int startX, startY, endX, endY;
    cin >> startX >> startY;
    cin >> endX >> endY;

    // 初始化起点
    visited[startX][startY] = true;
    path.emplace_back(startX, startY);

    // 检查起点和终点是否可通行
    if (maze[startX][startY] != 1 || maze[endX][endY] != 1) {
        cout << "-1" << endl;
        return 0;
    }

    // 执行 DFS
    dfs(startX, startY, endX, endY);

    // 如果没有找到路径
    if (!found) {
        cout << "-1" << endl;
    }

    return 0;
}
